import kotlinx.coroutines.sync.withLock

/**
 * Poblador automático idempotente para la base de datos local SQLite (Room v4).
 * Garantiza que al iniciar la aplicación existan:
 * - 50 pacientes adultos mayores activos
 * - 50 familiares / contactos de emergencia (1 por paciente)
 * - 10 recordatorios clínicos y cotidianos
 * - 5 juegos de estimulación cognitiva
 * - 125 sesiones en historial_estimulacion (2-3 por paciente con métricas de cada juego)
 */
object DatabaseSeeder {

    private val seedMutex = Mutex()

    suspend fun seedIfNeeded(db: SaraAppDatabase) = seedMutex.withLock {
        try {
            db.withTransaction {
                val pacienteDao = db.pacienteDao()
                val contactoDao = db.contactoEmergenciaDao()
                val recordatorioDao = db.recordatorioDao()
                val juegoDao = db.juegoDao()
                val historialDao = db.historialEstimulacionDao()

                var pacienteCount = pacienteDao.getPacienteCount()
                val juegoCountInicial = juegoDao.getJuegoCount()

                // Si existe únicamente el paciente stub antiguo (Id_paciente = 1L) sin juegos cargados,
                // se reemplaza limpiamente por el set completo de 50 pacientes.
                if (pacienteCount == 1 && juegoCountInicial == 0) {
                    val legacyStub = pacienteDao.getPacienteByIdIncluyendoInactivos(1L)
                    if (legacyStub != null) {
                        pacienteDao.deletePaciente(legacyStub)
                        pacienteCount = 0
                    }
                }

                val seededPacientes = if (pacienteCount == 0) {
                    pacienteDao.insertAll(buildPacientes())
                    contactoDao.insertAll(buildContactos())
                    true
                } else {
                    false
                }

                val seededJuegos = if (juegoDao.getJuegoCount() == 0) {
                    juegoDao.insertAll(buildJuegos())
                    true
                } else {
                    false
                }

                val seededRecordatorios = if (recordatorioDao.getRecordatorioCount() == 0 && pacienteDao.getPacienteCount() >= 50) {
                    recordatorioDao.insertAll(buildRecordatorios())
                    true
                } else {
                    false
                }

                val seededHistorial = if (historialDao.getHistorialCount() == 0 && juegoDao.getJuegoCount() >= 5 && pacienteDao.getPacienteCount() >= 50) {
                    historialDao.insertAll(buildHistorialEstimulacion())
                    true
                } else {
                    false
                }

                if (seededPacientes || seededJuegos || seededRecordatorios || seededHistorial) {
                    AppLogger.success(
                        "DatabaseSeeder",
                        "BD poblada: pacientes=${pacienteDao.getPacienteCount()}, familiares=${contactoDao.getContactoCount()}, recordatorios=${recordatorioDao.getRecordatorioCount()}, juegos=${juegoDao.getJuegoCount()}, historial=${historialDao.getHistorialCount()}"
                    )
                }
            }
        } catch (e: Exception) {
            AppLogger.error("DatabaseSeeder", "Error al poblar la base de datos local: ${e.message}")
        }
    }

